/**
 * 進度條插件（含縮圖預覽）
 */

import type { MpvPlugin } from '../../core/types/plugin';
import { ControlPlugin, ControlPluginOptions } from '../base/ControlPlugin';
import { formatTime } from '../../renderer/ui/utils';
import { WebGLVideoRenderer } from '../../renderer/video-player/webgl-renderer';
import styles from './styles.css?inline';

export interface ProgressPluginOptions extends ControlPluginOptions {
    /** 是否顯示 tooltip */
    showTooltip?: boolean;
    /** 是否啟用縮圖預覽 */
    showThumbnail?: boolean;
    /** 縮圖寬度 */
    thumbnailWidth?: number;
    /** 縮圖高度 */
    thumbnailHeight?: number;
}

/** 縮圖數據（從 thumbnail 事件接收） */
interface ThumbnailData {
    buffer: ArrayBuffer;
    width: number;
    height: number;
    format: 'rgba' | 'yuv420';
    rotation?: number;
    time: number;
}

export const ProgressPlugin: MpvPlugin<ProgressPluginOptions> = {
    name: 'progress',
    version: '1.0.0',
    styles,

    install(player, options = {}) {
        return new ProgressManager(player, {
            showTooltip: options.showTooltip ?? true,
            showThumbnail: options.showThumbnail ?? false,
            thumbnailWidth: options.thumbnailWidth ?? 160,
            thumbnailHeight: options.thumbnailHeight ?? 90,
            position: 'progress',
            order: 10,
        });
    },
};

export class ProgressManager extends ControlPlugin<Required<ProgressPluginOptions & { position: 'progress'; order: number }>> {
    readonly name = 'progress';

    // DO NOT initialize these fields here! JavaScript field initializers run AFTER super(),
    // which would reset values set during createEl() back to null.
    private progressBar!: HTMLElement | null;
    private progressBuffered!: HTMLElement | null;
    private progressPlayhead!: HTMLElement | null;
    private progressTooltip!: HTMLElement | null;
    private tooltipTime!: HTMLElement | null;
    private thumbnailCanvas!: HTMLCanvasElement | null;
    private thumbnailWrapper!: HTMLElement | null;

    // 縮圖相關
    private thumbnailRenderer!: WebGLVideoRenderer | null;
    private isHovering!: boolean;
    private lastThumbnailRequestTime = 0;
    private static readonly THUMBNAIL_THROTTLE_MS = 33; // ~30fps

    private isDragging = false;
    private wasPlayingBeforeDrag = false;

    protected createEl(): HTMLElement {
        // Initialize fields that cannot use field initializers (due to super() timing)
        this.isHovering = false;

        const container = document.createElement('div');
        container.className = 'vp-progress-container';
        const { thumbnailWidth, thumbnailHeight } = this.options;

        const thumbnailHtml = this.options.showThumbnail
            ? `<div class="vp-tooltip-thumbnail-wrapper" style="width: ${thumbnailWidth}px; height: ${thumbnailHeight}px; display: none;">
                    <canvas class="vp-tooltip-thumbnail" width="${thumbnailWidth}" height="${thumbnailHeight}"></canvas>
                </div>`
            : '';

        container.innerHTML = `
            <div class="vp-progress-bar">
                <div class="vp-progress-buffered"></div>
                <div class="vp-progress-playhead"></div>
            </div>
            <div class="vp-progress-tooltip${this.options.showThumbnail ? '' : ' no-thumbnail'}">
                ${thumbnailHtml}
                <span class="vp-tooltip-time">0:00</span>
            </div>
        `;

        this.progressBar = container.querySelector('.vp-progress-bar');
        this.progressBuffered = container.querySelector('.vp-progress-buffered');
        this.progressPlayhead = container.querySelector('.vp-progress-playhead');
        this.progressTooltip = container.querySelector('.vp-progress-tooltip');
        this.tooltipTime = container.querySelector('.vp-tooltip-time');
        this.thumbnailWrapper = container.querySelector('.vp-tooltip-thumbnail-wrapper');
        this.thumbnailCanvas = container.querySelector('.vp-tooltip-thumbnail');

        this.bindEvents(container);
        this.initializeThumbnail();

        // 監聽 tooltip 禁用事件（其他插件如 ABLoop 拖拽時會觸發）
        this.onPlayer('tooltipenabledchange', () => {
            this.hideTooltip();
            this.clearThumbnail();
        });

        return container;
    }

    /**
     * 覆寫插入方法 - 直接附加到 progress-section
     */
    protected insertElement(): void {
        if (!this.el) return;

        const container = this.getControlsContainer();
        if (!container) return;

        // 進度條直接附加到容器末尾（不使用 order-based 插入）
        container.appendChild(this.el);
    }

    private initializeThumbnail(): void {
        if (!this.options.showThumbnail || !this.thumbnailCanvas) return;

        // 創建 WebGL 渲染器（處理 YUV420 轉換）
        try {
            this.thumbnailRenderer = new WebGLVideoRenderer(this.thumbnailCanvas);
        } catch {
            console.warn('[ProgressPlugin] WebGL not available for thumbnails');
            return;
        }

        // 設置 thumbnail 渲染尺寸（讓 player 使用 GPU 縮放）
        const p = this.player as unknown as { setThumbnailSize?: (w: number, h: number) => void };
        p.setThumbnailSize?.(this.options.thumbnailWidth, this.options.thumbnailHeight);

        // 訂閱縮圖事件
        this.subscribeToThumbnailEvents();
    }

    private subscribeToThumbnailEvents(): void {
        // 監聽 thumbnail DOM 事件
        const handleThumbnail = (e: Event) => {
            const event = e as CustomEvent<ThumbnailData>;
            this.onThumbnailReceived(event.detail);
        };

        this.player.addEventListener('thumbnail', handleThumbnail);

        this.registerCleanup(() => {
            this.player.removeEventListener('thumbnail', handleThumbnail);
        });
    }

    private bindEvents(container: HTMLElement): void {
        // 進度條點擊/拖拽
        this.on(container, 'mousedown', (e) => {
            e.preventDefault();
            this.isDragging = true;
            this.wasPlayingBeforeDrag = !this.player.paused;

            // 啟用 scrubbing 模式（兩階段 seek：先 keyframe 快速顯示，停頓後補精準幀）
            this.player.setScrubbing(true);

            // 拖拽時完全隱藏 tooltip（主畫面已經在顯示預覽）
            this.hideTooltip();
            this.clearThumbnail();

            if (this.wasPlayingBeforeDrag) {
                this.player.pause();
            }
            this.updateSeekFromMouse(e);
        });

        // 進度條內的滑鼠移動：更新 tooltip（拖拽時不顯示 tooltip）
        this.on(container, 'mousemove', (e) => {
            if (this.isDragging) {
                this.updateSeekFromMouse(e);
            } else {
                this.updateTooltip(e);
            }
        });

        // document 層級的滑鼠移動：僅處理拖曳（支援超出進度條範圍）
        this.on(document, 'mousemove', (e) => {
            if (this.isDragging) {
                this.updateSeekFromMouse(e);
                // 拖拽時不顯示 tooltip，主畫面已經在顯示預覽
            }
        });

        this.on(document, 'mouseup', () => {
            if (this.isDragging) {
                this.isDragging = false;

                // 結束 scrubbing 模式
                this.player.setScrubbing(false);

                if (this.wasPlayingBeforeDrag) {
                    this.player.play();
                }
                // 拖曳結束後，如果不在進度條上，隱藏 tooltip
                if (!this.isHovering) {
                    this.hideTooltip();
                    this.clearThumbnail();
                }
            }
        });

        this.on(container, 'mouseenter', () => {
            this.isHovering = true;
            // 啟動 thumbnail rAF 渲染循環（和主播放器一樣）
            if (this.options.showThumbnail) {
                const p = this.player as unknown as { startThumbnailHover?: () => void };
                p.startThumbnailHover?.();
            }
        });

        this.on(container, 'mouseleave', () => {
            // 拖曳中不隱藏 tooltip
            if (!this.isDragging) {
                this.isHovering = false;
                this.hideTooltip();
                this.clearThumbnail();
                // 停止 thumbnail（和主視頻 mouseup 一樣）
                if (this.options.showThumbnail) {
                    const p = this.player as unknown as { stopThumbnailHover?: () => void };
                    p.stopThumbnailHover?.();
                }
            }
        });

        // 監聽播放進度
        this.onPlayer('timeupdate', () => this.updateProgress());
    }

    private updateSeekFromMouse(e: MouseEvent): void {
        if (!this.progressBar) return;
        const rect = this.progressBar.getBoundingClientRect();
        const percent = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
        const time = percent * this.player.duration;
        this.player.currentTime = time;
        this.updatePlayhead(percent);
    }

    private updateTooltip(e: MouseEvent): void {
        // 檢查核心是否允許顯示 tooltip（其他插件可能暫時禁用）
        if (!this.player.tooltipEnabled) return;
        if (!this.options.showTooltip || !this.progressBar || !this.progressTooltip) return;

        const rect = this.progressBar.getBoundingClientRect();
        const percent = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
        const time = percent * this.player.duration;

        if (this.tooltipTime) {
            this.tooltipTime.textContent = formatTime(time);
        }

        // 定位 tooltip
        this.progressTooltip.style.left = `${percent * 100}%`;
        this.progressTooltip.classList.add('visible');

        // 請求縮圖 - 拖拽時不請求，因為主畫面已經在顯示預覽
        if (this.options.showThumbnail && this.thumbnailRenderer && this.isHovering && !this.isDragging) {
            this.requestThumbnail(time);
        }
    }

    /**
     * 請求縮圖（帶節流）
     * 就是簡單地 seek 到指定時間，rAF 循環會自動渲染
     */
    private requestThumbnail(time: number): void {
        const now = performance.now();
        if (now - this.lastThumbnailRequestTime < ProgressManager.THUMBNAIL_THROTTLE_MS) {
            return;
        }
        this.lastThumbnailRequestTime = now;

        const p = this.player as unknown as {
            seekThumbnail?: (time: number) => void;
        };

        // 直接 seek（和主視頻 currentTime = x 一樣）
        p.seekThumbnail?.(time);
    }

    /**
     * 收到縮圖幀，直接渲染（模仿主播放器 Seek 的行為）
     */
    private onThumbnailReceived(data: ThumbnailData): void {
        if (!this.isHovering || !this.thumbnailRenderer || !this.thumbnailWrapper) return;

        const { buffer, width, height, format, rotation } = data;

        if (!buffer || width <= 0 || height <= 0) return;

        try {
            // 直接渲染最新幀（和主播放器 Seek 一樣）
            this.thumbnailRenderer.updateFrameFromBuffer(
                buffer,
                width,
                height,
                rotation ?? 0,
                format
            );

            // 顯示縮圖
            this.thumbnailWrapper.style.display = 'block';
        } catch (error) {
            console.error('[ProgressPlugin] Failed to render thumbnail:', error);
        }
    }

    private clearThumbnail(): void {
        if (this.thumbnailWrapper) {
            this.thumbnailWrapper.style.display = 'none';
        }
    }

    private hideTooltip(): void {
        this.progressTooltip?.classList.remove('visible');
    }

    private updateProgress(): void {
        if (this.isDragging) return;
        const percent = this.player.duration > 0
            ? this.player.currentTime / this.player.duration
            : 0;
        this.updatePlayhead(percent);
    }

    private updatePlayhead(percent: number): void {
        if (this.progressPlayhead) {
            this.progressPlayhead.style.left = `${percent * 100}%`;
        }
    }

    /** 獲取進度條元素（供其他插件使用，如 ABLoop） */
    getProgressBar(): HTMLElement | null {
        return this.progressBar;
    }

    /** 獲取 tooltip 容器（供縮圖插件使用） */
    getTooltip(): HTMLElement | null {
        return this.progressTooltip;
    }

    destroy(): void {
        // 銷毀縮圖渲染器
        if (this.thumbnailRenderer) {
            this.thumbnailRenderer.destroy();
            this.thumbnailRenderer = null;
        }

        super.destroy();
    }
}

